// One search per source rather than one per keyword.
//
// Stack Exchange allows 300 requests a day per IP without a key. Eight keywords
// checked hourly is 192 of them before anything else in the account runs, so
// the keywords go into one query joined by OR and the quota is read back from
// the answer.
//
// single-item input: the settings row.
const cfg = $('Settings').first().json;
const words = String(cfg.keywords || '')
  .split(',').map(function (w) { return w.trim(); }).filter(Boolean);

if (!words.length) {
  throw new Error('No keywords in Settings. Put the words somebody would use when they have the problem you solve.');
}

const days = Math.max(1, Number(cfg.max_age_days) || 7);
const cutoff = Math.floor(Date.now() / 1000) - days * 86400;

// One request per keyword, not one joined query. Measured 2026-09-01:
// `query=n8n` returned 2,652 hits over seven days and
// `query=n8n OR workflow automation` returned **zero** - Algolia has no boolean
// OR, it looked for documents containing the word "OR". Stack Exchange's `q` is
// the same kind of free text.
//
// That costs one Stack Exchange request per keyword per run, out of 300 a day
// per IP, which is why the list is capped and the remaining quota is reported.
const capped = words.slice(0, Math.max(1, Number(cfg.max_keywords) || 8));

return capped.map(function (w) {
  return { json: { keyword: w, cutoff: cutoff, window_days: days } };
});

// Both sources into one shape, then everything that cannot be helped removed.
//
// Read by name: the Merge above is a barrier that proves both searches have
// finished, and its output is two unrelated payloads in one stream.
const cfg = $('Settings').first().json;
const built = $('Build The Searches').first().json;
const minPoints = Number(cfg.min_engagement) || 0;

// One answer per keyword from each source, so every item has to be read - not
// just the first one.
function payloads(nodeName) {
  return $(nodeName).all().map(function (item) {
    const j = item.json || {};
    if (j.hits || j.items) { return j; }
    if (j.body && typeof j.body === 'object') { return j.body; }
    if (typeof j.data === 'string') {
      try { return JSON.parse(j.data); } catch (e) { return {}; }
    }
    return j;
  });
}

const hnPages = payloads('Ask Hacker News');
const sePages = payloads('Ask Stack Exchange');
const rows = [];
const seenKeys = new Set();

for (const h of hnPages.reduce(function (all, p) { return all.concat(p.hits || []); }, [])) {
  const isComment = (h._tags || []).indexOf('comment') >= 0;
  const text = String(h.comment_text || h.story_text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const title = String(h.title || h.story_title || '').trim();
  if (!title && !text) { continue; }
  rows.push({
    thread_key: 'hn:' + h.objectID,
    source: isComment ? 'Hacker News comment' : 'Hacker News',
    title: title || text.slice(0, 90),
    text: text.slice(0, 900),
    url: 'https://news.ycombinator.com/item?id=' + (isComment ? (h.story_id || h.objectID) : h.objectID),
    // A comment has no points of its own, so the story's engagement is the only
    // signal available and an unread story is an unread comment.
    engagement: Number(h.points || h.num_comments || 0),
    age_days: Math.round((Date.now() / 1000 - Number(h.created_at_i || 0)) / 86400),
    answered: false,
    closed: false,
    score: Number(h.points || 0),
  });
}

for (const q of sePages.reduce(function (all, p) { return all.concat(p.items || []); }, [])) {
  rows.push({
    thread_key: 'se:' + q.question_id,
    source: 'Stack Overflow',
    title: String(q.title || '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;/g, "'"),
    text: (q.tags || []).join(', '),
    url: String(q.link || ''),
    engagement: Number(q.view_count || 0),
    age_days: Math.round((Date.now() / 1000 - Number(q.creation_date || 0)) / 86400),
    answered: !!q.is_answered,
    closed: !!q.closed_date,
    score: Number(q.score || 0),
  });
}

const kept = rows.filter(function (r) {
  // The same thread matches two keywords and arrives twice.
  if (seenKeys.has(r.thread_key)) { return false; }
  seenKeys.add(r.thread_key);
  if (r.age_days > built.window_days) { return false; }
  // Closed, already answered, or downvoted. The API says so about every one of
  // them, and a reply on any of the three is time spent where nobody is
  // reading. The first result of a plain search scored -4.
  if (r.closed || r.answered || r.score < 0) { return false; }
  if (r.engagement < minPoints) { return false; }
  return true;
});

// Take from both sources in turn rather than taking the first N. Hacker News
// produces an order of magnitude more comments than Stack Overflow produces
// questions, so a plain slice fills the shortlist with HN and never reaches the
// questions - which are the only results that are guaranteed to be somebody
// asking for something. Seen live: eight of eight were HN comments.
const cap = Math.max(1, Number(cfg.max_threads) || 12);
const hnKept = kept.filter(function (r) { return r.source.indexOf('Hacker News') === 0; });
const seKept = kept.filter(function (r) { return r.source.indexOf('Hacker News') !== 0; });
const balanced = [];
for (let i = 0; balanced.length < cap && (i < hnKept.length || i < seKept.length); i++) {
  if (i < seKept.length && balanced.length < cap) { balanced.push(seKept[i]); }
  if (i < hnKept.length && balanced.length < cap) { balanced.push(hnKept[i]); }
}

// Never return zero items: the quiet branch below has to stay reachable and the
// quota reading has to survive either way.
return [{ json: {
  threads: balanced,
  found: rows.length,
  kept: kept.length,
  quota_left: sePages.length && sePages[sePages.length - 1].quota_remaining !== undefined
    ? Number(sePages[sePages.length - 1].quota_remaining)
    : null,
  window_days: built.window_days,
}}];

// What has not been looked at before.
//
// A thread is judged once. Without this the same Hacker News story arrives every
// morning for a week, and the model is paid to say the same thing about it each
// time.
//
// single-item input: the step above folds the run into one item.
//
// Read by name. `Read What You Have Seen` sits between that step and this one,
// and a Data Table read replaces the item with its rows - on an empty table
// that is one empty object, and every thread silently disappears.
const s = $('Read The Threads').first().json;

const seen = new Set();
for (const row of $('Read What You Have Seen').all()) {
  const j = row.json || {};
  if (j.thread_key) { seen.add(String(j.thread_key)); }
}

const fresh = (s.threads || []).filter(function (t) { return !seen.has(t.thread_key); });

const block = fresh.map(function (t, i) {
  return (i + 1) + '. [' + t.source + ', ' + t.age_days + ' days old, ' + t.engagement + ' points or views]\n' +
    '   ' + t.title + '\n' +
    (t.text ? '   ' + t.text.slice(0, 400) + '\n' : '');
}).join('\n');

return [{ json: {
  has_candidates: fresh.length > 0,
  fresh: fresh,
  fresh_count: fresh.length,
  block: block,
  found: s.found,
  kept: s.kept,
  quota_left: s.quota_left,
  window_days: s.window_days,
}}];

// Which threads survived the first pass.
//
// The default is no, and anything that is not exactly "yes" counts as no - the
// verdict comes back as "maybe", "Yes" and "possibly" often enough to plan for.
//
// single-item input: one judging call covers the whole shortlist.
const shortlist = $('Only The New Threads').first().json;
const raw = String(($input.first().json || {}).text || '');

let parsed = {};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) { parsed = {}; }
}

const verdicts = new Map();
for (const row of (parsed.threads || [])) {
  const n = Number(row && row.number);
  if (n >= 1 && n <= shortlist.fresh.length) {
    verdicts.set(n, {
      fit: String((row && row.fit) || '').toLowerCase().trim() === 'yes',
      why: String((row && row.why) || '').slice(0, 240),
    });
  }
}

const today = new Date().toISOString().slice(0, 10);
const judged = shortlist.fresh.map(function (t, i) {
  const v = verdicts.get(i + 1) || { fit: false, why: 'The model returned nothing about this one.' };
  return Object.assign({}, t, { fit: v.fit, why: v.why, seen_on: today });
});

const worth = judged.filter(function (t) { return t.fit; });

const block = worth.map(function (t, i) {
  return (i + 1) + '. ' + t.title + '\n   ' + (t.text || '').slice(0, 400) + '\n   why it fits: ' + t.why;
}).join('\n\n');

return [{ json: {
  judged: judged,
  worth: worth,
  worth_count: worth.length,
  block: block,
  has_worth: worth.length > 0,
}}];

// Put the drafts back on the threads they belong to.
//
// A draft that reads like an advertisement comes back as NOT_WORTH_POSTING, and
// that is a result rather than a failure: the thread stays in the digest with
// the reason, and nothing is written for it.
//
// single-item input: one call covers the shortlist.
const judged = $('Read The Judgement').first().json;
const raw = String(($input.first().json || {}).text || '');

let parsed = {};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) { parsed = {}; }
}

const drafts = new Map();
for (const row of (parsed.replies || [])) {
  const n = Number(row && row.number);
  if (n >= 1 && n <= judged.worth.length) {
    drafts.set(n, String((row && row.reply) || '').trim());
  }
}

const withDrafts = judged.worth.map(function (t, i) {
  const d = drafts.get(i + 1) || '';
  const refused = !d || /NOT_WORTH_POSTING/i.test(d);
  return Object.assign({}, t, {
    draft: refused ? '' : d,
    refused: refused,
  });
});

return [{ json: {
  replies: withDrafts,
  posted_nothing: true,
  ready: withDrafts.filter(function (t) { return !t.refused; }).length,
}}];

// The digest. The counts first, because "260 threads, 3 worth your time" is the
// finding and a list of 260 is a spreadsheet.
//
// single-item input: one item carries the whole run.
const cfg = $('Settings').first().json;
const found = $('Only The New Threads').first().json;
const judged = $('Read The Judgement').first().json;
const drafted = $input.first().json;

const parts = ['*Threads worth a reply about ' + cfg.product_name + '*'];
parts.push(
  found.found + ' results in the last ' + found.window_days + ' days, ' +
  found.kept + ' still open and unanswered, ' + found.fresh_count + ' not seen before, ' +
  judged.worth_count + ' worth replying to.'
);
if (found.quota_left !== null && found.quota_left < 50) {
  parts.push(':warning: Stack Exchange quota is down to ' + found.quota_left + ' of 300 for today.');
}

if (!drafted.replies.length) {
  parts.push('\nNothing this time. That is the normal answer.');
} else {
  for (const r of drafted.replies) {
    parts.push(
      '\n*' + r.title + '*' +
      '\n' + r.url + '  _(' + r.source + ', ' + r.age_days + ' days old)_' +
      '\n_why:_ ' + r.why +
      (r.refused
        ? '\n_no draft: the only honest reply here would read as an advertisement._'
        : '\n\n' + r.draft)
    );
  }
  parts.push('\n_Nothing has been posted. Read it, edit it, post it yourself._');
}

// Discord rejects anything over 2000 characters outright. A digest carrying
// three drafts goes past that easily, so it is cut here with a pointer to the
// table rather than rejected by the API.
const cap = Math.max(500, Number(cfg.max_message_chars) || 1900);
let message = parts.join(String.fromCharCode(10));
if (message.length > cap) {
  message = message.slice(0, cap - 90).replace(/[^\s]*$/, '') +
    String.fromCharCode(10, 10) + '_Cut to fit Discord. The rest is in the community_threads table._';
}

return [{ json: { message: message, ready: drafted.ready } }];

// One row per thread judged, whichever way it went. Storing only the good ones
// means the bad ones come back tomorrow and get judged again.
//
// single-item input: the judging step folds the run into one item.
const judged = $('Read The Judgement').first().json;
return (judged.judged || []).map(function (t) {
  return { json: {
    thread_key: t.thread_key,
    source: t.source,
    title: String(t.title || '').slice(0, 200),
    url: t.url,
    verdict: t.fit ? 'worth replying' : 'not a fit',
    seen_on: t.seen_on,
  }};
});
